use std::time::{Duration, Instant};

/// Wait before the next attempt, doubling each time.
pub fn retry_backoff(attempt: u32) -> Duration {
    Duration::from_millis(100 << attempt.min(6))
}

/// True while the retry window is still open.
pub fn window_open(started: Instant, budget: Duration) -> bool {
    window_open_at(started, Instant::now(), budget)
}

fn window_open_at(started: Instant, now: Instant, budget: Duration) -> bool {
    now.duration_since(started) < budget
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn window_is_open_at_start() {
        let started = Instant::now();
        assert!(window_open_at(started, started, Duration::from_millis(5)));
    }

    #[test]
    fn window_is_open_before_deadline() {
        let started = Instant::now();
        let now = started + Duration::from_millis(4);
        assert!(window_open_at(started, now, Duration::from_millis(5)));
    }

    #[test]
    fn window_is_closed_at_deadline() {
        let started = Instant::now();
        let now = started + Duration::from_millis(5);
        assert!(!window_open_at(started, now, Duration::from_millis(5)));
    }

    #[test]
    fn window_is_closed_after_deadline() {
        let started = Instant::now();
        let now = started + Duration::from_millis(6);
        assert!(!window_open_at(started, now, Duration::from_millis(5)));
    }

    #[test]
    fn zero_budget_is_closed() {
        let started = Instant::now();
        assert!(!window_open_at(started, started, Duration::ZERO));
    }
}
